// Removes one explicitly named acceptance fixture graph. This is intentionally
// not a broad cleanup: the required suffix must be a 12-character hex value
// generated by tests/financial-postgres.test.ts, and exactly its FIN-/OTH-
// branches are selected before dependent fixture records are deleted.
const { PrismaClient } = require('@prisma/client')

const suffix = process.env.SKOON_FINANCIAL_FIXTURE_SUFFIX
if (!/^[a-f0-9]{12}$/.test(suffix || '')) throw new Error('Set SKOON_FINANCIAL_FIXTURE_SUFFIX to the exact 12-character fixture suffix')

const prisma = new PrismaClient()

;(async () => {
  const codes = [`FIN-${suffix}`, `OTH-${suffix}`]
  const branches = await prisma.cafeBranch.findMany({ where: { code: { in: codes } }, select: { id: true, code: true } })
  if (branches.length !== 2 || branches.some((branch) => !codes.includes(branch.code))) throw new Error('Exact acceptance fixture branch pair was not found; refusing cleanup')
  const branchIds = branches.map((branch) => branch.id)
  const users = await prisma.user.findMany({ where: { branchId: { in: branchIds } }, select: { id: true } })
  const userIds = users.map((user) => user.id)
  const result = await prisma.$transaction(async (tx) => {
    const operations = await tx.financialOperation.deleteMany({ where: { branchId: { in: branchIds } } })
    const audits = await tx.auditLog.deleteMany({ where: { branchId: { in: branchIds } } })
    const movements = await tx.financialMovement.deleteMany({ where: { branchId: { in: branchIds } } })
    const shifts = await tx.shift.deleteMany({ where: { branchId: { in: branchIds } } })
    const fixtureUsers = await tx.user.deleteMany({ where: { id: { in: userIds }, branchId: { in: branchIds } } })
    const fixtureBranches = await tx.cafeBranch.deleteMany({ where: { id: { in: branchIds }, code: { in: codes } } })
    return { operations: operations.count, audits: audits.count, movements: movements.count, shifts: shifts.count, users: fixtureUsers.count, branches: fixtureBranches.count }
  })
  console.log(JSON.stringify(result))
})()
  .finally(() => prisma.$disconnect())
